solution.code:
import { readFileSync } from "fs";

const s = readFileSync(0, "utf8").trim();

const count = new Array(26).fill(0);
for (const c of s) count[c.charCodeAt(0) - 97]++;

const letters: number[] = [];
for (let i = 0; i < 26; i++) if (count[i] > 0) letters.push(i);

// 回数の降順、同じならアルファベット順（添字の昇順）
letters.sort((x, y) => count[y] - count[x] || x - y);
console.log(letters.map((i) => String.fromCharCode(97 + i) + " " + count[i]).join("\n"));
